/// <summary>
/// Calculates line amount.
/// </summary>
/// <param name = "_qty">Qty.</param>
/// <returns>Amount.</returns>
public AmountCur calcLineAmount(Qty _qty)
{
    AmountCur amount = next calcLineAmount(_qty);

    ItemId ItemId = this.parmItemId();

    if (PdsGlobal::pdsIsCWItem(ItemId)  || SalesLineSalesPurchLine::getPricedByWeightAttributeValue(ItemId))
    {
        SalesLine salesLine = this.parmSalesLine();

        WMSOrderTrans wmsOrderTrans;
        METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
        InventDim inventDim = salesLine.inventDim();
        UnitOfMeasureSymbol unitSales = salesLine.SalesUnit;
        AmountCur pickQty;

        select firstonly Qty from wmsOrderTrans
            where wmsOrderTrans.InventTransId == salesLine.InventTransId &&
                (wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Complete ||
                wmsOrderTrans.expeditionStatus == WMSExpeditionStatus::Activated);

        if (PdsGlobal::pdsIsCWItem(ItemId) && wmsOrderTrans.qty)
        {
            pickQty = wmsOrderTrans.qty;
        }
        else
        {
            select firstonly weight, NetWeight from metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == ItemId
                && metWHSPhysDimUOMSite.UOM == unitSales
                && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId;

            pickQty = metWHSPhysDimUOMSite.NetWeight * salesLine.SalesQty;
        }

        amount = pickQty * (salesLine.SalesPrice - salesLine.LineDisc);

        amount = round(amount, 0.01);
    }

    return amount;
}

/// <summary>
/// Calculates line amount forced.
/// </summary>
/// <param name = "_qty">Qty.</param>
/// <param name = "_checkPolicy">Check policy.</param>
/// <returns>Amount.</returns>
public AmountCur calcLineAmountForced(Qty _qty, PriceDiscPolicyCheckPolicy _checkPolicy)
