/// <summary>
/// Retrieves the "Priced by weight" attribute value for a given item.
/// </summary>
/// <param name="_itemId">
/// The unique identifier of the item (Product Number) whose attribute value is being checked.
/// </param>
/// <returns>
/// A boolean value indicating whether the item is priced by weight:
/// - true  → Item is priced by weight
/// - false → Item is not priced by weight or attribute not found
/// </returns>
/// <remarks>
/// The method queries the EcoResProductAttributeValueEntity table to find the BooleanValue
/// associated with the "Priced by weight" attribute for the specified item.
/// If the attribute exists, its BooleanValue is returned; otherwise, false is returned.
/// </remarks>
public static boolean getPricedByWeightAttributeValue(ItemId _itemId)
{
    #define.PricedByWeight('Priced by weight')
    EcoResProductAttributeValueEntity ecoResProdAttrValueEntity;
    boolean pricedByWeight = false;

    select firstonly BooleanValue
    from ecoResProdAttrValueEntity
    where ecoResProdAttrValueEntity.ProductNumber == _itemId
       && ecoResProdAttrValueEntity.AttributeName == #PricedByWeight;

    if (ecoResProdAttrValueEntity)
    {
        pricedByWeight = ecoResProdAttrValueEntity.BooleanValue;
    }

    return pricedByWeight;
}
